"use strict";

var C = require('./Constants');
var Exceptions = require('./Exceptions');
var Utils = require('./Utils');
var UA = require('./UA');
var URI = require('./URI');
var NameAddrHeader = require('./NameAddrHeader');
var Grammar = require('./Grammar');
var WebSocketInterface = require('./WebSocketInterface');
var debug = require('debug')('CRTC');
var RTCStatsMonitor = require('./RTCStatsMonitor');
var MediaEffectsComposer = require('./MediaEffectsComposer/MediaEffectsComposer');
var AiNoiseSuppression = require('./AiNoiseSuppression/AiNSEngine');
var MetaHumanClient = require('./MetaHumanClient');
debug('version %s', '__VERSION__');
(function () {
  if (typeof window.CustomEvent === 'function') return;
  function CustomEvent(event, params) {
    params = params || {
      bubbles: false,
      cancelable: false,
      detail: undefined
    };
    var evt = document.createEvent('CustomEvent');
    evt.initCustomEvent(event, params.bubbles, params.cancelable, params.detail);
    return evt;
  }
  CustomEvent.prototype = window.Event.prototype;
  window.CustomEvent = CustomEvent;
})();

/**
 * Expose the CRTC module.
 */
module.exports = {
  C,
  Exceptions,
  Utils,
  UA,
  URI,
  NameAddrHeader,
  WebSocketInterface,
  MediaEffectsComposer,
  Mixer: MediaEffectsComposer,
  AiNoiseSuppression,
  MetaHumanClient,
  Grammar,
  // 保留历史公开名称；新旧入口共用同一套统计实现，避免两套逻辑产生不同结果。
  getStats: RTCStatsMonitor,
  RTCStatsMonitor,
  // Expose the debug module.
  debug: require('debug'),
  get name() {
    return '__TITLE__';
  },
  get version() {
    return '__VERSION__';
  }
};